if (!function_exists('get_url_memurlar')) {
    function get_url_memurlar($url)
    {
        $curl = curl_init($url);
        curl_setopt($curl, CURLOPT_TIMEOUT, "50");
        curl_setopt($curl, CURLOPT_USERAGENT, "Mozilla/5.0 (Windows NT 6.1) AppleWebKit/534.30 (KHTML, like Gecko) Chrome/12.0.742.122 Safari/534.30");
        curl_setopt($curl, CURLOPT_RETURNTRANSFER, TRUE);
        curl_setopt($curl, CURLOPT_HEADER, 0);
        curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, FALSE);

        $curlResult = curl_exec($curl);
        curl_close($curl);
        return iconv('iso-8859-9', 'utf-8', str_replace(array("\n", "\t", "\r"), null, $curlResult));
    }
}

if(!function_exists('ilan_post'))
{
    function ilan_post($url, $postfields)
    {
        $curl = curl_init($url);
        curl_setopt($curl, CURLOPT_TIMEOUT, "50");
        curl_setopt($curl, CURLOPT_USERAGENT, "Mozilla/5.0 (Windows NT 6.1) AppleWebKit/534.30 (KHTML, like Gecko) Chrome/12.0.742.122 Safari/534.30");
        curl_setopt($curl, CURLOPT_RETURNTRANSFER, TRUE);
        curl_setopt($curl, CURLOPT_HEADER, 0);
        curl_setopt($curl, CURLOPT_HTTPHEADER, explode("\n", 'Host: www.ilan.gov.tr
User-Agent: Mozilla/5.0 (Macintosh; Intel Mac OS X 10.15; rv:94.0) Gecko/20100101 Firefox/94.0
Accept: text/plain
Accept-Language: en-US,en;q=0.5
Accept-Encoding: gzip, deflate, br
Content-Type: application/json-patch+json
Pragma: no-cache
Cache-Control: no-cache
Expires: Sat, 01 Jan 2000 00:00:00 GMT
X-Requested-With: XMLHttpRequest
X-Request-Origin: IGT-UI
Content-Length: '.strlen($postfields).'
Origin: https://www.ilan.gov.tr
Connection: keep-alive
Referer: https://www.ilan.gov.tr/ilan/tum-ilanlar?q=Sa%C4%9Fl%C4%B1k
Cookie: _ga=GA1.3.625916998.1614252368
