Sec-Fetch-Mode: cors
Sec-Fetch-Site: same-origin
TE: trailers'));
        curl_setopt($curl, CURLOPT_SSL_VERIFYPEER, FALSE);
        curl_setopt($curl, CURLOPT_POST, TRUE);
        curl_setopt($curl, CURLOPT_POSTFIELDS, $postfields);

        $curlResult = curl_exec($curl);
        curl_close($curl);
        return $curlResult;
    }
}

