if (!function_exists('memur_egitim_durumu')) {
    function memur_egitim_durumu($meslek)
    {
        $kaynak = get_url_memurlar('https://www.memurlar.net/maas/' . $meslek . '/');
        preg_match_all('@<select name="Salary_Condition" id="_Salary_Condition">(.*?)</select>@si', $kaynak, $egitimList);

        return $egitimList;
    }
}

if(!function_exists('memur_maasi_hesapla')) {
    function memur_maasi_hesapla()
    {
        $job = $_GET['job'];
        unset($_GET['job']);
        $kaynak = get_url_memurlar($ad ='https://www.memurlar.net/maas/'.$job.'/?action=salary&advanced=true'.http_build_query($_GET));
        preg_match_all('@<table class="Salary_Result"><tr><td style="color:#113ac1; font-size:140%; font-weight:bold; text-align:center;" colspan="3">(.*?)</td></tr>@si', $kaynak, $title);
        preg_match_all('@<table class="Salary_Result">(.*?)</table>@si', $kaynak, $result);
        preg_match_all('@<tr><td class="Header">İstihaklar(.*?)<tr><td class="Header">Kesintiler@si', $result[1][0], $result_istihaklar);
        preg_match_all('@<tr><td class="Header">Kesintiler(.*?)<tr><td class="Header">Toplam@si', $result[1][0], $result_kesintiler);
        preg_match_all('@<tr><td class="Header">Toplam(.*?)<tr><td class="Header">Not@si', $result[1][0], $result_toplam);
        preg_match_all('@<tr><td class="Header">Not(.*?)</table>@si', $result[0][0], $result_not);

        preg_match_all('@<tr><td>(.*?)</td><td style="text-align:right;">(.*?)</td><td style="text-align:right;">(.*?)</td></tr>@si',$result_istihaklar[1][0], $istihaklar_tr);
        preg_match_all('@<tr><td>(.*?)</td><td style="text-align:right;">(.*?)</td><td style="text-align:right;">(.*?)</td></tr>@si',$result_kesintiler[1][0], $kesintiler_tr);
        preg_match_all('@<tr><td style="font-weight:bold;">(.*?)</td><td style="font-weight:bold;text-align:right;"></td><td style="font-weight:bold;text-align:right;">(.*?)</td></tr>@si',$result_toplam[1][0], $toplam_tr);
        preg_match_all('@<tr><td>(.*?)</td><td style="text-align:right;">(.*?)</td><td style="text-align:right;">(.*?)</td></tr>@si',$result_not[1][0], $not_tr);

        return array(
            'title' => $title[1][0],
            'istihaklar' => $istihaklar_tr,
            'kesintiler' => $kesintiler_tr,
            'toplam' => $toplam_tr,
            'not' => $not_tr,
        );
    }
}

